    r3 = 0x3638EF1D;   /* 1/362880 */
    f2 = f2 + f3;
    f2 = f2 * f1;
    r3 = 0xB9500D01;   /* -1/5040 */
    f2 = f2 + f3;
    f2 = f2 * f1;
    r3 = 0x3C088889;   /* 1/120 */
    f2 = f2 + f3;
    f2 = f2 * f1;
    r3 = 0xBE2AAAAB;   /* -1/6 */
    f2 = f2 + f3;
    f2 = f2 * f1;
    r3 = 0x3F800000;   /* 1.0 */
    f2 = f2 + f3;
    f0 = f0 * f2;                 /* sin(x)      */
    f0 = f0 + f0;                 /* k = 2sin(x) */
    dm(_osc_k_C1_TEST_OSC) = f0;
    /* cos(x) in the same z, for the amplitude scale -- see the
     * _COS_TAYLOR note: the invariant is held at 1, where the state
     * reaches 1/cos(x), so the output is scaled by cos(x) and the
     * level cell means exactly what it says at every frequency. */
    r2 = 0x310F76C7;   /* 1/479001600 */
    f2 = f2 * f1;
    r3 = 0xB493F27E;   /* -1/3628800 */
    f2 = f2 + f3;
    f2 = f2 * f1;
    r3 = 0x37D00D01;   /* 1/40320 */
    f2 = f2 + f3;
    f2 = f2 * f1;
    r3 = 0xBAB60B61;   /* -1/720 */
    f2 = f2 + f3;
    f2 = f2 * f1;
    r3 = 0x3D2AAAAB;   /* 1/24 */
    f2 = f2 + f3;
    f2 = f2 * f1;
    r3 = 0xBF000000;   /* -1/2 */
    f2 = f2 + f3;
    f2 = f2 * f1;
    r3 = 0x3F800000;   /* 1.0 */
    f2 = f2 + f3;                 /* cos(x) */
    dm(_osc_cos_C1_TEST_OSC) = f2;
    /* A FREQUENCY CHANGE RESTARTS THE RESONATOR at a known phase.
     * Moving k without it steps the amplitude invariant by up to
     * |dk| and leaves the block-rate Newton correction -- a FIRST-
     * order step, sized for drift -- to recover a jump it was never
     * sized for. A sweep re-measures over a fresh window anyway, so
     * the phase discontinuity costs nothing. */
    r1 = 0x00000000;   /* 0.0 */
    dm(_osc_s_C1_TEST_OSC) = f1;
    r1 = 0x3F800000;   /* 1.0 */
    dm(_osc_c_C1_TEST_OSC) = f1;

    /* ---- generate the block the NEXT chain pass will inject ---- */
.osc_gen_C1_TEST_OSC:
    f8 = dm(_osc_k_C1_TEST_OSC);
    f9 = dm(_osc_s_C1_TEST_OSC);
    f10 = dm(_osc_c_C1_TEST_OSC);
    f11 = dm(_osc_level_C1_TEST_OSC);
    r12 = 0x4D800000;                   /* 2^28 */
    f11 = f11 * f12;
    f12 = dm(_osc_cos_C1_TEST_OSC);
    f11 = f11 * f12;                    /* amplitude, pre-scaled */
    i4 = _osc_blk_sc_C1_TEST_OSC;
    l4 = 0;
    i5 = _osc_blk_q_C1_TEST_OSC;
    l5 = 0;
    lcntr = DSP4_BLOCK_SIZE, do .osc_gen_lp_C1_TEST_OSC until lce;
        f0 = f8 * f10;
        f9 = f9 + f0;               /* x += k*y  */
        f0 = f8 * f9;
        f10 = f10 - f0;             /* y -= k*x' */
        dm(i4, 1) = f9;
        dm(i4, 1) = f10;
        f1 = f9 * f11;
        r1 = fix f1;
.osc_gen_lp_C1_TEST_OSC:
        dm(i5, 1) = r1;
    /* ---- ONE NEWTON STEP ON THE AMPLITUDE INVARIANT --------------
     * E = x^2 + k*x*y + y^2 is exactly conserved by the recurrence
     * in exact arithmetic, and is 1.0 by construction at the reset
     * above, so 1/sqrt(E) ~= 1.5 - E/2 to second order. Two passes
     * of that -- quadratic convergence from anywhere in [0.3, 2],
     * and overkill for the 1e-7 a block of float32 actually drifts.
     * Once per BLOCK, not once per sample. */
    f0 = f9 * f9;
    f1 = f10 * f10;
    f0 = f0 + f1;
    f1 = f9 * f10;
    f1 = f1 * f8;
    f0 = f0 + f1;                   /* E = x^2 + y^2 + k*x*y */
    r2 = 0x3FC00000;   /* 1.5 */
    r3 = 0x3F000000;   /* 0.5 */
    f4 = f3 * f0;
    f4 = f2 - f4;                   /* g ~= 1/sqrt(E) */
    f5 = f4 * f4;
    f5 = f5 * f0;
    f5 = f3 * f5;
    f5 = f2 - f5;
    f4 = f4 * f5;                   /* g, refined     */
    f9 = f9 * f4;
    f10 = f10 * f4;
    /* ---- THE BACKSTOP. A self-test node that can publish garbage
     * is worse than one that publishes nothing, because garbage
     * reads as a measurement. Two instructions catch a NaN -- it is
     * the only value not equal to itself -- and two more catch a
     * state that has run away; either restarts the resonator at the
     * known (0, 1). Once per block, against a recurrence whose
     * invariant is now correct and which therefore should never
     * need it. */
    comp(f9, f9);
    if ne jump (pc, .osc_panic_C1_TEST_OSC);
    comp(f10, f10);
    if ne jump (pc, .osc_panic_C1_TEST_OSC);
    f0 = abs f9;
    r1 = 0x42800000;   /* 64.0 */
    comp(f0, f1);
    if gt jump (pc, .osc_panic_C1_TEST_OSC);
    f0 = abs f10;
    comp(f0, f1);
    if gt jump (pc, .osc_panic_C1_TEST_OSC);
    dm(_osc_s_C1_TEST_OSC) = f9;
    dm(_osc_c_C1_TEST_OSC) = f10;
    rts;
.osc_panic_C1_TEST_OSC:
    r1 = 0x00000000;   /* 0.0 */
    dm(_osc_s_C1_TEST_OSC) = f1;
    r1 = 0x3F800000;   /* 1.0 */
    dm(_osc_c_C1_TEST_OSC) = f1;
#endif
    rts;
_C1_TEST_OSC_process.end:
